#!/usr/bin/env python3
"""NEW kernel-only R3 build/cost evidence, not a firmware acceptance replay."""
import pathlib,os,subprocess,hashlib,re,json
root=pathlib.Path(__file__).resolve().parents[1];out=root/'build/english6';tc=pathlib.Path(os.environ.get('JIELI_TOOLCHAIN',root/'build/deps/jieli-linux-toolchains-20260730.1'));cc=tc/'pi32v2/bin/clang'
flags=['-target','pi32v2','-mcpu=r3','-mfprev1','-O2','-ffp-contract=off','-Ibuild/english6','-Iexperiments/english6','-Icore']
for name,extra in [('proto6-native',[]),('proto6-single-core',['-DP6_FORCE_SINGLE_CORE=1'])]:subprocess.run([str(cc),*flags,*extra,'-c','experiments/english6/proto6.c','-o',str(out/(name+'.o'))],cwd=root,check=True)
(out/'native-sizes.c').write_text('#include "kira.h"\nchar prototype_state_size[sizeof(p6_state)];\nchar prototype_engine_size[sizeof(k9_engine)];\n');subprocess.run([str(cc),*flags,'-c',str(out/'native-sizes.c'),'-o',str(out/'native-sizes.o')],cwd=root,check=True)
size=subprocess.check_output(['size',str(out/'proto6-native.o')],text=True);symbols=subprocess.check_output(['nm','-S',str(out/'native-sizes.o')],text=True);dis=subprocess.check_output([str(tc/'common/bin/objdump'),'-d','-mcpu=r3',str(out/'proto6-native.o')],text=True);(out/'proto6-native.dis').write_text(dis)
values={name:int(n,16) for n,name in re.findall(r'^[0-9a-f]+\s+([0-9a-f]+)\s+\w\s+(prototype_\w+)',symbols,re.M)};hashes={n:hashlib.sha256((out/(n+'.o')).read_bytes()).hexdigest() for n in ['proto6-native','proto6-single-core']};assert len(set(hashes.values()))==1
report={'object_size_output':size,'native_sizes':values,'object_hashes':hashes,'forced_single_core':'Kernel has no workers/CPU2; forced-single-core define produces identical object. Not a whole firmware test.','stack':'R3 p6_process prologue saves rets+r15..r4 (52 bytes) then reserves 92 bytes = 144-byte kernel frame; no nested calls in object. Wrapper/interrupt stack unmeasured.','device_cpu':'UNVERIFIED: native object is not an on-device timing measurement; 256/44100 = 5.805ms callback requirement must be measured on FM-1.','heap_allocation':False};(out/'native.json').write_text(json.dumps(report,indent=2)+'\n');print(size);print(symbols)
